def materialize():
    for relative,record in EMBEDDED.items():
        data=record["source"].encode()
        if hashlib.sha256(data).hexdigest()!=record["sha256"]:raise RuntimeError("embedded source identity mismatch")
        path=BASE/relative
        if path.exists():
            if hashlib.sha256(path.read_bytes()).hexdigest()!=record["sha256"]:raise RuntimeError("existing source differs: "+str(path))
        else:
            path.parent.mkdir(parents=True,exist_ok=True)
            with path.open("xb") as stream:stream.write(data)
        if hashlib.sha256(path.read_bytes()).hexdigest()!=record["sha256"]:raise RuntimeError("materialized source changed")
def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--stage",choices=("unpack","pairs","spectra","anchors","original-inventory","primary1920","exact-controls","exact-crosschecks","chain-inventory","spectral-evidence","inventory-evidence","checks","render","plot-check","recovery","admit-recovery"),default="render")
    args=parser.parse_args()
    if socket.gethostname()!="gpu":raise RuntimeError("execute only on the declared CPU box192.168.1.93")
    BASE.mkdir(parents=True,exist_ok=True)
    disk=os.statvfs(BASE)
    if disk.f_bavail*disk.f_frsize<100*1024**3:raise RuntimeError("required /data reserve below100GiB")
    current=os.getpriority(os.PRIO_PROCESS,0)
    if current<10:os.nice(10-current)
    materialize()
    if args.stage=="unpack":return
    env=os.environ.copy()
    for name in ("OMP_NUM_THREADS","OPENBLAS_NUM_THREADS","MKL_NUM_THREADS","NUMEXPR_NUM_THREADS"):env[name]="1"
    env.update(TMPDIR=str(BASE/"tmp"),MPLCONFIGDIR=str(BASE/"tmp/matplotlib"),XDG_CACHE_HOME=str(BASE/"tmp"),PYTHONDONTWRITEBYTECODE="1")
    (BASE/"tmp").mkdir(exist_ok=True)
    original="code/producer_final_embedded_v1.py"
    commands={
      "pairs":[original,"--stage","pairs","--workers","16"],
      "spectra":[original,"--stage","spectra","--workers","16"],
      "anchors":[original,"--stage","anchors","--workers","16"],
      "original-inventory":[original,"--stage","inventory","--workers","16"],
      "primary1920":["code/primary1920_spectrum_v1.py"],
      "exact-controls":["code/exact_chain_lp_v1.py"],
      "exact-crosschecks":["code/exact_chain_paper_v1.py"],
      "chain-inventory":["code/chain_inventory_refined_v1.py"],
      "spectral-evidence":["code/spectral_saved_evidence_primary1920_v1.py"],
      "inventory-evidence":["code/final_chain_saved_evidence_v1.py"],
      "checks":["code/refined_checks_render_v1.py","--stage","checks"],
      "render":["code/refined_checks_render_v3.py","--stage","render"],
      "plot-check":["code/final_plot_artifact_check_v1.py"],
      "recovery":[original,"--stage","recovery","--workers","16"],
      "admit-recovery":[original,"--stage","admit-recovery","--workers","16"]}
    if args.stage=="exact-controls":
        cached=BASE/"raw/chain_exact_v1/manufactured_controls.json"
        if cached.exists():
            if hashlib.sha256(cached.read_bytes()).hexdigest()!="08e09d0392b68385e43679af45b79d0749c117022df0bfe15790eddfff2c26ae":raise RuntimeError("existing control identity differs")
            return
    command=[PYTHON,str(BASE/commands[args.stage][0]),*commands[args.stage][1:]]
    subprocess.run(command,cwd=BASE,env=env,check=True)
if __name__=="__main__":main()
